import numpy as np

def wml_all(r, J, Ks, skip=0):
    T = r.shape[0]
    f = formation_returns(r, J, skip)
    W = np.zeros(r.shape)
    for s in range(J + skip, T):
        W[s] = cohort_weights(f[s])
    S = W @ r.T  # S[s, t]: cohort s in month t
    out = {}
    for K in Ks:
        start = J + skip + K - 1
        out[K] = np.array([S[t - K + 1:t + 1, t].mean()
                           for t in range(start, T)])
    return out

import numpy as np

def decile_spread_by_month(r, J, K):
    T, n = r.shape
    f = formation_returns(r, J)
    D = np.zeros((T, 10, n))
    for s in range(J, T):
        rank = np.argsort(np.argsort(f[s], kind="stable"), kind="stable")
        dec = rank * 10 // n
        for k in range(10):
            D[s, k, dec == k] = 1 / np.sum(dec == k)
    out = []
    for t in range(J + K - 1, T):
        book = D[t - K + 1:t + 1].mean(axis=0)  # (10, n)
        out.append(book @ r[t])
    return np.array(out)
